//! Job manager for ZiSK SNARK proof generation.
//!
//! Mirrors `FriJobManager` in architecture:
//! - Batches enter via `add_job` when ZiSK data is available
//! - External provers pick jobs via `pick_next_job` (with timeout-based reassignment)
//! - Provers submit ZiSK SNARK proofs via `submit_proof`
//! - Completed proofs are paired with Airbender SNARKs for multi-proof composition
//!
//! The ZiSK job lifecycle is independent of the FRI/Airbender SNARK lifecycle.
//! A batch only becomes a ZiSK job when both:
//! 1. ZiSK data was generated by the prover input generator
//! 2. The Airbender SNARK has been submitted (the batch is ready for proving on L1)

use crate::prover_api::zisk_proof_constants::{ZISK_PUBLIC_VALUES_BYTES, ZISK_SNARK_PROOF_BYTES};
use std::collections::HashMap;
use std::time::Duration;
use tokio::sync::Mutex;
use zksync_os_batcher_metrics::BatchExecutionStage;
use zksync_os_batch_types::batcher_model::{
    FriProof, MultiProofSnarkProof, SignedBatchEnvelope, SnarkProof,
};
use zksync_os_l1_sender::commands::prove::ProofCommand;
use tokio::sync::mpsc::Sender;

/// Maximum number of pending + assigned ZiSK jobs.
/// Prevents unbounded memory growth if ZiSK provers are slow or offline.
const MAX_TOTAL_JOBS: usize = 50;

/// Data stored per ZiSK job: the ZiSK prover input and the Airbender SNARK.
pub struct ZiskJobData {
    /// Bincode-serialized BatchInput for cargo-zisk.
    pub zisk_data: Vec<u8>,
    /// Airbender SNARK proof bytes (already submitted and verified).
    pub era_proof: Vec<u8>,
    /// Proving execution version (for verifier routing on L1).
    pub proving_execution_version: u32,
    /// Batch envelopes for downstream pipeline.
    pub batches: Vec<SignedBatchEnvelope<FriProof>>,
}

/// Job metadata returned to the prover on pick.
pub struct ZiskJob {
    pub batch_number: u64,
    pub vk_hash: String,
    pub zisk_data: Vec<u8>,
}

/// Errors from ZiSK proof submission.
#[derive(Debug, thiserror::Error)]
pub enum ZiskSubmitError {
    #[error("unknown batch {0}")]
    UnknownJob(u64),
    #[error("invalid proof size: {got} bytes, expected {expected}")]
    InvalidProofSize { got: usize, expected: usize },
    #[error("invalid public values size: {got} bytes, expected {expected}")]
    InvalidPublicValuesSize { got: usize, expected: usize },
    #[error("batch commitment mismatch: ZiSK public values first 32 bytes do not match batch commitment")]
    CommitmentMismatch,
    #[error("downstream channel closed")]
    DownstreamClosed,
}

/// Inner state protected by a single mutex to avoid lock ordering issues.
struct ZiskJobState {
    pending: HashMap<u64, ZiskJobData>,
    assigned: HashMap<u64, (String, std::time::Instant, ZiskJobData)>,
}

/// Manages ZiSK SNARK proof jobs with pick/submit assignment model.
pub struct ZiskJobManager {
    state: Mutex<ZiskJobState>,
    /// Assignment timeout — if a prover doesn't submit within this, the job is reassigned.
    assignment_timeout: Duration,
    /// Channel to send completed multi-proofs downstream.
    prove_sender: Sender<ProofCommand>,
}

impl ZiskJobManager {
    pub fn new(
        prove_sender: Sender<ProofCommand>,
        assignment_timeout: Duration,
    ) -> Self {
        Self {
            state: Mutex::new(ZiskJobState {
                pending: HashMap::new(),
                assigned: HashMap::new(),
            }),
            assignment_timeout,
            prove_sender,
        }
    }

    /// Add a batch ready for ZiSK proving.
    pub async fn add_job(&self, batch_number: u64, job_data: ZiskJobData) -> Result<(), ZiskJobData> {
        let mut state = self.state.lock().await;
        if state.pending.len() + state.assigned.len() >= MAX_TOTAL_JOBS {
            let pending_count = state.pending.len();
            let assigned_count = state.assigned.len();
            tracing::error!(
                batch = batch_number,
                pending = pending_count,
                assigned = assigned_count,
                max = MAX_TOTAL_JOBS,
                "ZiSK job queue full — rejecting job. ZiSK provers may be offline."
            );
            return Err(job_data);
        }

        tracing::info!(
            batch = batch_number,
            zisk_data_bytes = job_data.zisk_data.len(),
            era_proof_bytes = job_data.era_proof.len(),
            "ZiSK job added"
        );
        state.pending.insert(batch_number, job_data);
        Ok(())
    }

    /// Pick the next available ZiSK job for a prover.
    pub async fn pick_next_job(&self, prover_id: &str) -> Option<ZiskJob> {
        let now = std::time::Instant::now();
        let mut state = self.state.lock().await;

        // Return timed-out assigned jobs to pending.
        let timed_out: Vec<u64> = state.assigned
            .iter()
            .filter(|(_, (_, assigned_at, _))| now.duration_since(*assigned_at) >= self.assignment_timeout)
            .map(|(&batch, _)| batch)
            .collect();
        for batch in timed_out {
            if let Some((old_prover, _, data)) = state.assigned.remove(&batch) {
                tracing::warn!(batch, old_prover, "ZiSK job timed out, returning to pending");
                state.pending.insert(batch, data);
            }
        }

        // Pick oldest pending.
        let batch_number = *state.pending.keys().min()?;
        let job_data = state.pending.remove(&batch_number)?;

        let vk_hash = job_data
            .batches
            .first()
            .and_then(|b| b.batch.verification_key_hash().ok())
            .map(|h| format!("0x{h}"))
            .unwrap_or_else(|| {
                tracing::warn!(batch = batch_number, "VK hash missing");
                String::new()
            });

        let zisk_data = job_data.zisk_data.clone();
        state.assigned.insert(batch_number, (prover_id.to_string(), now, job_data));

        tracing::info!(
            batch = batch_number,
            prover_id,
            "ZiSK job assigned"
        );

        Some(ZiskJob {
            batch_number,
            vk_hash,
            zisk_data,
        })
    }

    /// Submit a ZiSK SNARK proof for a batch.
    ///
    /// Validates proof sizes and batch commitment, pairs with the cached
    /// Airbender SNARK, and sends the combined MultiProof downstream.
    /// On downstream send failure, the job is returned to pending queue.
    pub async fn submit_proof(
        &self,
        batch_number: u64,
        proof: Vec<u8>,
        public_values: Vec<u8>,
        prover_id: &str,
    ) -> Result<(), ZiskSubmitError> {
        // Validate sizes.
        if proof.len() != ZISK_SNARK_PROOF_BYTES {
            return Err(ZiskSubmitError::InvalidProofSize {
                got: proof.len(),
                expected: ZISK_SNARK_PROOF_BYTES,
            });
        }
        if public_values.len() != ZISK_PUBLIC_VALUES_BYTES {
            return Err(ZiskSubmitError::InvalidPublicValuesSize {
                got: public_values.len(),
                expected: ZISK_PUBLIC_VALUES_BYTES,
            });
        }

        // Remove from assigned jobs.
        let job_data = {
            let mut state = self.state.lock().await;
            match state.assigned.remove(&batch_number) {
                Some((_, _, data)) => data,
                None => return Err(ZiskSubmitError::UnknownJob(batch_number)),
            }
        };

        // Validate batch commitment using the shared verifier.
        if let Some(first_batch) = job_data.batches.first() {
            let stored = first_batch
                .batch
                .batch_info
                .clone()
                .into_stored();
            let prev = &first_batch.batch.previous_stored_batch_info;
            if let Err(msg) = crate::prover_api::zisk_proof_verifier::verify_zisk_snark_public_values(
                &prev.state_commitment,
                &stored,
                &public_values,
            ) {
                tracing::error!(batch = batch_number, "{msg}");
                self.state.lock().await.pending.insert(batch_number, job_data);
                return Err(ZiskSubmitError::CommitmentMismatch);
            }
        }

        tracing::info!(
            batch = batch_number,
            prover_id,
            era_proof_bytes = job_data.era_proof.len(),
            zisk_proof_bytes = proof.len(),
            "combined Airbender + ZiSK multi-proof ready"
        );

        // Compose MultiProof and send downstream.
        let snark_proof = SnarkProof::MultiProof(MultiProofSnarkProof {
            era_proof: job_data.era_proof,
            zisk_proof: proof,
            zisk_public_values: public_values,
            proving_execution_version: job_data.proving_execution_version,
        });

        let batches = job_data
            .batches
            .into_iter()
            .map(|b: SignedBatchEnvelope<FriProof>| b.with_stage(BatchExecutionStage::SnarkProvedReal))
            .collect();

        let proof_command = ProofCommand::new(batches, snark_proof);
        if let Err(err) = self.prove_sender.send(proof_command).await {
            // Downstream closed — recover the job data from the failed ProofCommand.
            // The ProofCommand owns the data; extract and return to pending.
            let failed_command = err.0;
            let (batches_back, snark_back) = failed_command.into_parts();
            if let SnarkProof::MultiProof(mp) = snark_back {
                let recovered = ZiskJobData {
                    zisk_data: vec![], // original data already consumed, but proof is intact
                    era_proof: mp.era_proof,
                    proving_execution_version: mp.proving_execution_version,
                    batches: batches_back,
                };
                tracing::error!(
                    batch = batch_number,
                    "downstream channel closed, returning ZiSK job to pending queue"
                );
                self.state.lock().await.pending.insert(batch_number, recovered);
            }
            return Err(ZiskSubmitError::DownstreamClosed);
        }

        Ok(())
    }

    /// Check if there are pending or assigned ZiSK jobs.
    pub async fn has_pending_jobs(&self) -> bool {
        let state = self.state.lock().await;
        !state.pending.is_empty() || !state.assigned.is_empty()
    }
}
